#!/bin/bash
# Apply changes safely while keeping mTLS logic!
sed -i '/func (s \*Server) handleMeshV2Broadcast/,/^}/c\func (s *Server) handleMeshV2Broadcast(w http.ResponseWriter, r *http.Request) {\n\tmode := "cloud"\n\tif os.Getenv("OHC_STANDALONE") == "true" {\n\t\tmode = "standalone"\n\t}\n\ttelemetry.RecordMeshBroadcast(r.Context(), mode)\n\n\tif r.Method != http.MethodPost {\n\t\thttp.Error(w, "method not allowed", http.StatusMethodNotAllowed)\n\t\treturn\n\t}\n\n\t// Enforce mTLS checks\n\tif r.TLS == nil || len(r.TLS.PeerCertificates) == 0 {\n\t\thttp.Error(w, "mTLS SPIFFE identity required", http.StatusForbidden)\n\t\treturn\n\t}\n\tcert := r.TLS.PeerCertificates[0]\n\tif len(cert.URIs) == 0 || cert.URIs[0].Scheme != "spiffe" {\n\t\thttp.Error(w, "mTLS SPIFFE identity required", http.StatusForbidden)\n\t\treturn\n\t}\n\n\tif s.meshBroker != nil {\n\t\t// Let the unified HTTP handler take over now that we checked SPIFFE auth\n\t\t// Note that HandleBroadcast enforces its own method check, JSON parsing, etc.\n\t\torchestration_mesh.HandleBroadcast(s.meshBroker)(w, r)\n\t\treturn\n\t}\n\thttp.Error(w, "mesh broker not initialized", http.StatusInternalServerError)\n}' srcs/server/dashboard/server.go

sed -i 's/agentProviderRegistry \*agents\.Registry/agentProviderRegistry \*agents\.Registry\n\tmeshBroker            orchestration_mesh.MeshBroker/' srcs/server/dashboard/server.go

sed -i 's|"github.com/onehumancorp/mono/srcs/server/orchestration"|"github.com/onehumancorp/mono/srcs/server/orchestration"\n\torchestration_mesh "github.com/onehumancorp/mono/srcs/server/orchestration/mesh"|' srcs/server/dashboard/server.go
